// Replay positive construction certificates for E1083/E1286.
// Source bitmaps are independently regenerated by spectrum_effective_bound.cpp.
// No model search or optimizer is used by this checker.
#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <map>
#include <set>
#include <vector>

using Order = std::int64_t;
using Word = std::uint64_t;
constexpr Order source_bound = 1000000000;

void require(bool condition, const char* message) {
  if (!condition) { std::fprintf(stderr, "%s\n", message); std::exit(1); }
}

std::vector<Word> read_bitmap(const char* path) {
  std::ifstream stream(path, std::ios::binary);
  std::vector<Word> result((source_bound + 128) / 64);
  constexpr Order bytes = (source_bound + 8) / 8;
  stream.read(reinterpret_cast<char*>(result.data()), bytes);
  require(stream.gcount() == bytes, "Truncated source bitmap");
  return result;
}

bool member(const std::vector<Word>& bitmap, Order n) {
  return 0 <= n && n <= source_bound && ((bitmap[n / 64] >> (n % 64)) & 1);
}

// Set exactly those target bits offset+r for which the source supplies r,
// with 0 <= r <= end (and r != 0 when identifying a common point).
void translate(const std::vector<Word>& source, std::vector<Word>& target,
               Order lo, Order hi, Order offset, Order end, bool common,
               Order clip_lo = -1, Order clip_hi = -1) {
  const Order a = std::max<Order>(common, std::max(lo, clip_lo) - offset);
  const Order b = std::min({end, source_bound, (clip_hi < 0 ? hi : std::min(hi, clip_hi)) - offset});
  if (a > b) return;
  const Order first = a + offset - lo, last = b + offset - lo;
  const Order fw = first/64, lw = last/64;
  const Order bit_offset = lo+64*fw-offset;
  const Order word = bit_offset >= 0 ? bit_offset/64 : (bit_offset-63)/64;
  const int bits = bit_offset-64*word;
  auto boundary = [&](Order index) {
    Word value = 0;
    if (index >= 0 && index < Order(source.size())) value = source[index] >> bits;
    if (bits && index+1 >= 0 && index+1 < Order(source.size()))
      value |= source[index+1] << (64-bits);
    return value;
  };
  const Word first_mask = ~Word(0) << (first%64);
  const Word last_mask = last%64 == 63 ? ~Word(0) : (Word(1) << (last%64+1))-1;
  if (fw == lw) {
    target[fw] |= boundary(word) & first_mask & last_mask;
    return;
  }
  target[fw] |= boundary(word) & first_mask;
  // Interior words lie wholly within the certified source interval. Separate
  // boundary handling lets the compiler vectorize these contiguous shifts.
  const Word* __restrict input = source.data()+word+1;
  Word* __restrict output = target.data()+fw+1;
  if (bits) {
    for (Order j = 0; j < lw-fw-1; ++j)
      output[j] |= (input[j] >> bits) | (input[j+1] << (64-bits));
  } else {
    for (Order j = 0; j < lw-fw-1; ++j) output[j] |= input[j];
  }
  target[lw] |= boundary(word+lw-fw) & last_mask;
}

// Most late certificate rows address chunks whose bits are already almost all
// proved. Cache only the assertion that an entire block is all ones. Skipping
// such a block cannot alter the union; the final bit-by-bit check still runs.
void translate_cached(const std::vector<Word>& source, std::vector<Word>& target,
                      std::vector<unsigned char>& full, Order lo, Order hi,
                      Order offset, Order end, bool common) {
  constexpr Order block_words = 512, block_bits = 64*block_words;
  const Order first = std::max(lo, offset+common), last = std::min({hi, offset+end, offset+source_bound});
  if (first > last) return;
  for (Order b = (first-lo)/block_bits; b <= (last-lo)/block_bits; ++b) {
    if (full[b]) continue;
    translate(source, target, lo, hi, offset, end, common,
              lo+b*block_bits, lo+(b+1)*block_bits-1);
    const auto start = target.begin()+b*block_words;
    const auto stop = target.begin()+std::min<Order>((b+1)*block_words, target.size());
    full[b] = std::all_of(start, stop, [](Word word) { return word == ~Word(0); });
  }
}

int main(int argc, char** argv) {
  if (argc != 10 && argc != 11) {
    std::fprintf(stderr, "usage: %s HAVE IDEM COVERS RECIPES GAPS ORIGIN CUTOFF END CHUNK [BEGIN]\n", argv[0]);
    return 2;
  }
  const auto source = read_bitmap(argv[1]), idempotent = read_bitmap(argv[2]);
  const Order origin = std::atoll(argv[6]), cutoff = std::atoll(argv[7]);
  const Order end = std::atoll(argv[8]), chunk = std::atoll(argv[9]);
  const Order begin = argc == 11 ? std::atoll(argv[10]) : origin;
  require(0 < origin && origin <= cutoff && cutoff <= end && 0 < chunk,
          "Invalid finite interval");
  require(origin <= begin && begin <= end && (begin-origin)%chunk == 0,
          "Invalid partial-check boundary");

  std::set<Order> gaps;
  std::ifstream gap_file(argv[5]);
  require(bool(gap_file), "Missing gap file");
  for (Order n; gap_file >> n;) {
    require(origin <= n && n < cutoff && gaps.insert(n).second,
            "A gap reaches the claimed tail, or is duplicated");
  }
  require(gap_file.eof(), "Malformed gap file");

  std::vector<int> primes;
  for (int p = 2; p < 200000; ++p) {
    bool prime = true;
    for (int d = 2; d*d <= p; ++d) if (p % d == 0) { prime = false; break; }
    if (prime) primes.push_back(p);
  }
  auto design = [&](Order k, Order q) {
    require(2 <= k && k < 200000 && q >= k, "Invalid transversal parameters");
    require(member(idempotent, k) && member(idempotent, k+1), "Missing idempotent block model");
    for (int p : primes) {
      if (p >= k) break;
      if (q % p == 0) {
        Order power = 1;
        do { q /= p; power *= p; } while (q % p == 0);
        require(power >= k, "Prime-power factor does not supply this transversal design");
      }
    }
  };

  // Auxiliary group orders below the beginning of the verified interval.
  // Each recipe uses only source orders, so no dependency ordering is needed.
  std::set<Order> extra;
  std::ifstream recipe_file(argv[4]);
  require(bool(recipe_file), "Missing recipe file");
  Order n, k, q, common;
  while (recipe_file >> n >> k >> q >> common) {
    if (k == -2) {
      // Binary-simplex half-groups: further fields are the smaller block
      // order b, the power-of-two gap h, and the nonzero-fibre flag.
      Order b, h, nonzero;
      require(bool(recipe_file >> b >> h >> nonzero), "Truncated binary recipe");
      require((common == 0 || common == 1) && (nonzero == 0 || nonzero == 1),
              "Invalid binary recipe flags");
      require(2 <= h && h < 100000 && (h & (h-1)) == 0 && 2 <= b && b < 100000,
              "Invalid binary block parameters");
      require(nonzero || b-h+1 >= 0, "Negative number of full groups");
      require(member(idempotent, b) && member(idempotent, b+h),
              "Missing binary transversal blocks");
      require(q > 0 && q % 2 == 0 && (q & -q) >= 2*h,
              "The even field is too small for the binary subspace");
      const Order need = nonzero ? b+2*h-2 : b+h-1;
      require(need < 200000 && q >= need, "Binary design exceeds the checked range");
      Order rest = q;
      for (int p : primes) {
        if (p >= need) break;
        if (rest % p == 0) {
          Order power = 1;
          do { rest /= p; power *= p; } while (rest % p == 0);
          require(power >= need, "A field factor has too few binary-design directions");
        }
      }
      const Order factor = nonzero ? 2*(b+h)-1 : 2*b+1;
      require(n == factor*(q/2)+common && member(source, q+common) &&
              member(source, q/2+common), "Binary recipe lacks groups or has the wrong order");
      require(extra.insert(n).second, "Duplicate auxiliary recipe");
      continue;
    }
    if (k == 0) {
      // Cartesian product: the last two fields are its two source orders.
      require(member(source, q) && member(source, common) && n == q*common,
              "Product recipe lacks its factors or has the wrong order");
      require(extra.insert(n).second, "Duplicate auxiliary recipe");
      continue;
    }
    require(common == 0 || common == 1, "Invalid common-point flag");
    design(k, q);
    require(k*q <= n, "Negative hole");
    const Order r = n-k*q;
    require(r >= common && r <= q+common, "Hole too large or missing common point");
    require(member(source, q+common) && member(source, r), "Auxiliary recipe lacks group models");
    require(extra.insert(n).second, "Duplicate auxiliary recipe");
  }
  require(recipe_file.eof(), "Malformed auxiliary recipe");

  std::ifstream covers(argv[3]);
  require(bool(covers), "Missing cover file");
  Order row_lo, row_hi;
  bool pending = bool(covers >> row_lo >> row_hi >> k >> q >> common);
  Order count = 0;
  // Chunks may be checked in parallel. A group may use only a strictly earlier
  // chunk. Once all chunks pass, induction on chunk number discharges every
  // such dependency, regardless of the order in which checks were executed.
  for (Order lo = begin; lo <= end; lo += chunk) {
    const Order hi = std::min(lo+chunk-1, end), size = hi-lo+1;
    std::vector<Word> target((size+63)/64);
    std::vector<unsigned char> full((target.size()+511)/512);
    translate(source, target, lo, hi, 0, source_bound, false);
    for (auto it = extra.lower_bound(lo); it != extra.end() && *it <= hi; ++it)
      target[(*it-lo)/64] |= Word(1) << ((*it-lo)%64);
    while (pending && row_lo == lo) {
      require(row_hi == hi && (common == 0 || common == 1), "Invalid cover chunk");
      design(k, q);
      const Order group = q+common;
      require(member(source, group) || extra.count(group) ||
              (origin <= group && group < lo && !gaps.count(group)),
              "The full-group order has no earlier construction");
      translate_cached(source, target, full, lo, hi, k*q, group, common);
      ++count;
      pending = bool(covers >> row_lo >> row_hi >> k >> q >> common);
    }
    require(!pending || row_lo > lo, "Cover rows are not ordered by chunk");
    // Declared gaps are allowed only strictly below the final cutoff.
    for (auto it = gaps.lower_bound(lo); it != gaps.end() && *it <= hi; ++it)
      target[(*it-lo)/64] |= Word(1) << ((*it-lo)%64);
    for (Order j = 0; j < Order(target.size()); ++j) {
      Word required = ~Word(0);
      if (j+1 == Order(target.size()) && size % 64)
        required = (Word(1) << (size % 64)) - 1;
      require((target[j] & required) == required, "The finite cover has an undeclared gap");
    }
    if ((lo-origin)/chunk % 1000 == 0)
      std::fprintf(stderr, "Verified through %lld (%lld translated prefixes)\n",
                   static_cast<long long>(hi), static_cast<long long>(count));
  }
  require(!pending && covers.eof(), "Unconsumed or malformed cover rows");
  std::printf("Checked [%lld, %lld] using %lld positive translated prefixes (only earlier dependencies).\n",
              static_cast<long long>(std::max(begin, cutoff)), static_cast<long long>(end),
              static_cast<long long>(count));
  return 0;
}
